```java
import android.os.Bundle;
import android.widget.ArrayAdapter;
import android.widget.ListView;

import androidx.appcompat.app.AppCompatActivity;

import java.util.ArrayList;

public class MainActivity extends AppCompatActivity {

    private ListView listView;
    private ArrayList<Integer> intList;
    private ArrayList<String> strList;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        // Initialize ListView
        listView = findViewById(R.id.listView);

        // Initialize ArrayLists
        intList = new ArrayList<>();
        strList = new ArrayList<>();

        // Add items to ArrayLists
        intList.add(1);
        intList.add(2);
        intList.add(3);

        strList.add("Apple");
        strList.add("Banana");
        strList.add("Cherry");

        // Create ArrayAdapter to convert ArrayLists into ListView items
        ArrayAdapter<Integer> intAdapter = new ArrayAdapter<>(this, android.R.layout.simple_list_item_1, intList);
        ArrayAdapter<String> strAdapter = new ArrayAdapter<>(this, android.R.layout.simple_list_item_1, strList);

        // Set ListView adapter to show items
        listView.setAdapter(intAdapter); // Change to strAdapter to show strings instead of integers
    }
}
```

this builds two ArrayLists - one of ints, one of strings - drops a few sample items in each, then wraps them in ArrayAdapters so the ListView can actually render them. swap `intAdapter` for `strAdapter` in that last line if you want the strings showing instead, wan~
